from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import numpy as np

VASP_INCAR_TEMPLATE = {
    "SYSTEM": "SSB material",
    "PREC": "Accurate",
    "ENCUT": 520,
    "EDIFF": 1e-6,
    "EDIFFG": -0.02,
    "ISIF": 3,
    "IBRION": 2,
    "NSW": 100,
    "ISMEAR": 0,
    "SIGMA": 0.05,
    "LREAL": "Auto",
    "LORBIT": 11,
    "LWAVE": False,
    "LCHARG": False,
    "IVDW": 11,
    "ALGO": "Normal",
    "NELMIN": 5,
    "NELM": 100,
}

VASP_KPOINTS_TEMPLATE = {
    "comment": "Auto-generated KPOINTS",
    "generation_scheme": "Gamma-centered",
    "kppa": 1000,
}


def _calc_kpoints(kppa: int, num_atoms: int) -> tuple[int, int, int]:
    nk = round((kppa / num_atoms) ** (1 / 3))
    return max(1, nk), max(1, nk), max(1, nk)


def generate_vasp_inputs(
    structure_cif: str,
    output_dir: str | Path,
    incar_overrides: dict[str, Any] | None = None,
    functional: str = "PBE",
    kppa: int = 1000,
    potcar_dir: str | None = None,
) -> dict[str, str]:
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    poscar_path = output_dir / "POSCAR"
    try:
        from pymatgen.core import Structure
        struct = Structure.from_str(structure_cif, fmt="cif")
        struct.to(fmt="poscar", filename=str(poscar_path))
    except Exception:
        poscar_path.write_text(structure_cif)

    incar = dict(VASP_INCAR_TEMPLATE)
    if incar_overrides:
        incar.update(incar_overrides)
    incar["SYSTEM"] = incar.get("SYSTEM", "SSB material")
    incar_path = output_dir / "INCAR"
    _write_incar(incar, incar_path)

    kpoints_a, kpoints_b, kpoints_c = _calc_kpoints(kppa, 20)
    kpoints_path = output_dir / "KPOINTS"
    kpoints_content = f"""Auto-generated KPOINTS
0
Gamma-centered
{kpoints_a} {kpoints_b} {kpoints_c}
0 0 0
"""
    kpoints_path.write_text(kpoints_content)

    if potcar_dir:
        try:
            from pymatgen.io.vasp import Potcar
            from pymatgen.core import Structure
            struct = Structure.from_str(structure_cif, fmt="cif")
            potcar = Potcar(symbols=[str(el) for el in struct.species])
            potcar.write_file(str(output_dir / "POTCAR"))
        except Exception:
            pass

    return {
        "poscar": str(poscar_path),
        "incar": str(incar_path),
        "kpoints": str(kpoints_path),
        "potcar": str(output_dir / "POTCAR") if potcar_dir else "",
    }


def _write_incar(incar: dict[str, Any], path: Path) -> None:
    lines = ["INCAR generated by scandium-labs SSB pipeline\n"]
    for key, val in incar.items():
        if isinstance(val, bool):
            val_str = ".TRUE." if val else ".FALSE."
        elif isinstance(val, str):
            val_str = val
        else:
            val_str = str(val)
        lines.append(f"  {key} = {val_str}\n")
    path.write_text("".join(lines))


def generate_qe_inputs(
    structure_cif: str,
    output_dir: str | Path,
    pseudopotentials: dict[str, str] | None = None,
) -> dict[str, str]:
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    try:
        from pymatgen.core import Structure
        struct = Structure.from_str(structure_cif, fmt="cif")
    except Exception:
        output_dir.joinpath("ssb.in").write_text(structure_cif)
        return {"input": str(output_dir / "ssb.in"), "fallback": "raw_cif"}

    alat = struct.lattice.a
    atomic_species: dict[str, int] = {}
    for el in struct.species:
        atomic_species[str(el)] = atomic_species.get(str(el), 0) + 1

    species_lines = []
    for sp, count in atomic_species.items():
        pp = pseudopotentials.get(sp, f"{sp}.UPF") if pseudopotentials else f"{sp}.UPF"
        mass = 1.0
        species_lines.append(f"  {sp}  {mass}  {pp}")

    atom_lines = []
    for site in struct.sites:
        atom_lines.append(f"  {site.species_string}  {site.a}  {site.b}  {site.c}")

    kpoints = _calc_kpoints(1000, len(struct.sites))

    qe_input = f"""&CONTROL
  calculation = 'vc-relax'
  prefix = 'ssb'
  outdir = './out'
  pseudo_dir = './pseudo'
  verbosity = 'high'
  etot_conv_thr = 1.0e-5
  forc_conv_thr = 1.0e-4
/

&SYSTEM
  ibrav = 0
  nat = {len(struct.sites)}
  ntyp = {len(atomic_species)}
  ecutwfc = 60
  ecutrho = 480
  occupations = 'smearing'
  smearing = 'gaussian'
  degauss = 0.02
/

&ELECTRONS
  conv_thr = 1.0e-8
  mixing_beta = 0.7
  electron_maxstep = 200
/

&IONS
  ion_dynamics = 'bfgs'
/

&CELL
  cell_dynamics = 'bfgs'
  press_conv_thr = 0.5
/

CELL_PARAMETERS (alat={alat:.6f})
  {struct.lattice.matrix[0][0] / alat:.10f}  {struct.lattice.matrix[0][1] / alat:.10f}  {struct.lattice.matrix[0][2] / alat:.10f}
  {struct.lattice.matrix[1][0] / alat:.10f}  {struct.lattice.matrix[1][1] / alat:.10f}  {struct.lattice.matrix[1][2] / alat:.10f}
  {struct.lattice.matrix[2][0] / alat:.10f}  {struct.lattice.matrix[2][1] / alat:.10f}  {struct.lattice.matrix[2][2] / alat:.10f}

ATOMIC_SPECIES
{chr(10).join(species_lines)}

ATOMIC_POSITIONS (crystal)
{chr(10).join(atom_lines)}

K_POINTS automatic
  {kpoints[0]} {kpoints[1]} {kpoints[2]}  0 0 0
"""
    input_path = output_dir / "ssb.in"
    input_path.write_text(qe_input)
    return {"input": str(input_path)}


def write_inputs(
    structure_cif: str,
    output_dir: str | Path,
    code: str = "vasp",
    **kwargs: Any,
) -> dict[str, str]:
    if code.lower() == "vasp":
        return generate_vasp_inputs(structure_cif, output_dir, **kwargs)
    elif code.lower() in ("qe", "quantum_espresso", "quantum-espresso"):
        return generate_qe_inputs(structure_cif, output_dir, **kwargs)
    else:
        raise ValueError(f"Unsupported code: {code}")
